int main() {
  int tt; 
  for (cin >> tt; tt; --tt) {
    int n, N; cin >> N; n = N;
    array<int, 2> candidates = {-1, -1};

    while (n > 4) {
      if (query(n - 1, n) != query(n, n - 1)) {
        candidates = {n - 1, n}; break;
      } else n -= 2;
    }

    if (candidates[0] != -1) {
      int not_candidate = (candidates[0] == N - 1) ? N - 2 : N;

      if (query(candidates[0], not_candidate) != query(not_candidate, candidates[0])) {
